window.GT_META = {"built_from_index_updated_at": "2026-09-30T15:00:00+08:00", "paper_counts": {"A": 4, "B": 8, "C": 3, "total": 15}, "watchlist_count": 0, "chapter_count": 13, "site": {"title": "游戏技术知识网络", "brand": "GT", "brand_text": "游戏技术知识网络", "footer": "游戏技术知识网络 · 物理 × 渲染 × 其它支柱 · 论文持续入库", "description": "从 PBD / 球谐等既有储备出发，梳理物理模拟、光照渲染与相邻分支的时间脉络、落地应用与论文索引。"}};
window.GT_CONTENT = [{"id": "home", "module": "导论", "title": "知识网络首页", "keywords": "home 地图 物理 渲染 PBD 球谐 Lumen", "html": "<h1>游戏技术知识网络</h1>\n<p class=\"lead\">把「物理怎么动」和「画面怎么亮」两条主线，以及相邻支柱，收成可继续长论文的知识网络。</p>\n<h2>你的起点</h2>\n<ul>\n<li><strong>物理</strong>：熟悉到 <strong>PBD / 基于位置的约束</strong>；工业侧听过 <strong>有限元（FEM/FEA）</strong>。</li>\n<li><strong>光照</strong>：熟悉到 <strong>球谐 / PRT</strong>；学过 <strong>PBR</strong>；对 <strong>光追 / Lumen</strong> 需补齐。</li>\n<li><strong>学习姿态</strong>：不必手写每个 shader，但要能 <strong>读 AI 代码、按现象收窄问题</strong>。</li>\n</ul>\n<h2>地图</h2>\n<table><tr><th>主干</th><th>你停在哪</th><th>往后看</th></tr><tr><td>物理</td><td>PBD</td><td>XPBD → MPM/IPC；游戏布料仍常是 XPBD</td></tr><tr><td>光照</td><td>SH/PRT</td><td>SSAO/SSR/探针 → RT → Lumen</td></tr><tr><td>几何</td><td>（可后补）</td><td>Nanite 等虚拟几何</td></tr><tr><td>其它</td><td>—</td><td>动画 / 网络 / 开世界流式</td></tr></table>\n<h2>和 UE5「两大算法」的关系</h2>\n<p><strong>Nanite</strong> 与 <strong>Lumen</strong> 是渲染线突破，不在 PBD/FEM 物理脉络里：一个管几何细节，一个管动态全局光。</p>\n<h2>关键要点</h2>\n<ul>\n<li>物理与光照是并行学科；PBD 是交互物理的长寿默认，不是一切物理的终点。</li>\n<li>近十年游戏布料没有「取代 PBD」的全民换代；突破多在接触保证（IPC）与跨材料（MPM）。</li>\n<li>光追没有取代光栅，而是嵌进混合管线；Lumen 是生产级动态 GI。</li>\n</ul>\n"}, {"id": "how-to-use", "module": "导论", "title": "怎么用这套知识库", "keywords": "阅读路径 分档 A B C 监控 watchlist", "html": "<h1>怎么用这套知识库</h1>\n<h2>阅读顺序（建议）</h2>\n<ol>\n<li><a href=\"#home\" target=\"_blank\" rel=\"noopener noreferrer\">知识网络首页</a> — 站位与地图  </li>\n<li><a href=\"#physics-map\" target=\"_blank\" rel=\"noopener noreferrer\">物理家族地图</a> → <a href=\"#physics-timeline\" target=\"_blank\" rel=\"noopener noreferrer\">物理时间脉络</a>  </li>\n<li><a href=\"#lighting-timeline\" target=\"_blank\" rel=\"noopener noreferrer\">光照时间脉络</a> → <a href=\"#pbr-rt-lumen\" target=\"_blank\" rel=\"noopener noreferrer\">PBR·光追·Lumen</a>  </li>\n<li><a href=\"#other-pillars\" target=\"_blank\" rel=\"noopener noreferrer\">其它支柱</a> — 知道还有哪些分支  </li>\n<li><a href=\"#watchlist\" target=\"_blank\" rel=\"noopener noreferrer\">每日候选项</a> / <a href=\"#paper-index\" target=\"_blank\" rel=\"noopener noreferrer\">分档论文</a> — 跟新文</li>\n</ol>\n<h2>分档含义</h2>\n<table><tr><th>档</th><th>含义</th></tr><tr><td><strong>A</strong></td><td>主张清晰，有对照或强影响力；尽量有核心介绍</td></tr><tr><td><strong>B</strong></td><td>有实证，但样本/外推/复现有软肋</td></tr><tr><td><strong>C</strong></td><td>愿景、技术报告，或与主线关联偏弱</td></tr></table>\n<p>评级基于摘要级审阅，不是全文同行评审。</p>\n<h2>日更怎么来的</h2>\n<p><code>scripts/monitor_papers.py</code> 每天从 arXiv / Semantic Scholar / DBLP 拉候选，写入：</p>\n<ul>\n<li><code>indexes/game-tech/watchlist.json</code></li>\n<li><code>indexes/game-tech/inbox/YYYY-MM-DD.json</code></li>\n</ul>\n<p><strong>不会自动入库</strong>。正式入库：</p>\n<pre><code>python indexes/game-tech/_add_paper.py --arxiv-id ... --title &quot;...&quot; --tier B --tier-reason &quot;...&quot; --tags physics,mpm\npython scripts/build_site.py</code></pre>\n<h2>本地预览</h2>\n<pre><code>python scripts/build_site.py\npython -m http.server 8080 --directory site</code></pre>\n<p>打开 <code>http://localhost:8080</code>。</p>\n<h2>关键要点</h2>\n<ul>\n<li>教程章节是骨架；论文按 <code>tags</code> / <code>knowledge_ids</code> 挂到章节。</li>\n<li>日更先看候选项，再人工或 Agent 分档入库。</li>\n</ul>\n"}, {"id": "learning-stance", "module": "导论", "title": "学习姿态：能读能调即可", "keywords": "AI 编码 调试 读代码 验收", "html": "<h1>学习姿态：能读能调即可</h1>\n<h2>以前</h2>\n<p>学 PBD 往往要：微分方程怎么迭代、公式怎么推、怎么落代码、怎么进 CPU/GPU。</p>\n<h2>现在更划算的能力</h2>\n<p>底层实现大量可由 AI 出初稿，但 AI 替代的是「写出来」，不是「做对并扛住上线」。</p>\n<p>目标画像：</p>\n<ol>\n<li><strong>读</strong>：认出预测、约束投影、速度回写、碰撞各在哪。  </li>\n<li><strong>验</strong>：单约束、静止堆叠、加倍时间步等小实验。  </li>\n<li><strong>指范围</strong>：按现象收窄模块（穿模→接触；顿挫→迭代/子步；软硬随帧率变→柔度/Δt）。</li>\n</ol>\n<h2>概念够用 vs 仍要碰底层</h2>\n<table><tr><th>场景</th><th>深度</th></tr><tr><td>引擎参数、选型、内容管线</td><td>概念 + 失败模式</td></tr><tr><td>改约束、修爆炸、压移动端</td><td>工程层：读伪代码能改</td></tr><tr><td>自研效果 / 论文落地</td><td>至少完整闭环过一个小求解器</td></tr></table>\n<h2>关键要点</h2>\n<ul>\n<li>不写（或不常写）底层，但要能读、能验、能按现象收窄问题。</li>\n<li>完全不懂验收标准时，AI 会放大「错得像那么回事」的风险。</li>\n</ul>\n"}, {"id": "physics-map", "module": "物理模拟", "title": "物理家族地图", "keywords": "PBD XPBD FEM MPM SPH IPC ABD PD Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics ipc-2020 A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling 1802.06895 XPBD: Position-Based Simulation of Compliant Constrained Dynamics 1602.07039 Position Based Dynamics pbd-2007 A Position Based Material Point Method pb-mpm-2024 XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity 2405.11694 Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges fluid-survey-2024 A Review of Differentiable Simulators diffsim-review-2024 Efficient GPU Cloth Simulation with Non-distance Barriers and Subspace Reuse cloth-gpu-2024 Power Plastics: A Hybrid Lagrangian/Eulerian Solver for Mesoscale Inelastic Flows power-plastics-2023 Affine Body Dynamics: Fast, Stable and Intersection-free Simulation of Stiff Materials abd-2022 Neural SPH: Improved Neural Modeling of Lagrangian Fluid Dynamics neural-sph-2024", "html": "<h1>物理家族地图</h1>\n<p class=\"lead\">「看起来都是微分方程 + 迭代」——对的是 1990s 学术主线。后来分叉在于：<strong>迭代在解什么未知量</strong>。</p>\n<h2>三派</h2>\n<table><tr><th>家族</th><th>未知量</th><th>典型</th><th>用途</th></tr><tr><td>力 / 加速度</td><td>速度或加速度（ODE/PDE）</td><td>FEM、Baraff 布料、NS 流体</td><td>准、贵</td></tr><tr><td>位置约束</td><td>位置修正（几何投影）</td><td>Jakobsen → PBD → XPBD → PBF</td><td>游戏默认</td></tr><tr><td>混合 / 势垒</td><td>粒子状态或接触势优化</td><td>MPM；IPC/ABD</td><td>跨材料；无穿插保证</td></tr></table>\n<h2>PBD 是不是核心？</h2>\n<p>在 <strong>实时游戏布料/绳/软体</strong> 圈里：<strong>是</strong>，至今默认气质仍是 PBD→XPBD。  </p>\n<p>在 <strong>整个物理模拟</strong> 里：不是唯一核心——电影雪泥是 MPM，高精度接触是 IPC。</p>\n<h2>近十年有没有 breakthrough？</h2>\n<ul>\n<li>若标准是「再出一个全民替换游戏布料默认算法」：<strong>基本没有</strong>（XPBD 是精修）。  </li>\n<li>若看全领域：<strong>有</strong>——IPC 接触保证、MPM 成熟、神经/可微物理；只是多数没回到日常 XPBD 布料工作流。</li>\n</ul>\n<h2>和有限元</h2>\n<p>工业力学分析常说的「拆成很多点/单元」= <strong>有限元（FEM/FEA）</strong>。  </p>\n<p>ACG 近十年是让 <strong>轻量 FEM + 隐式 + GPU/降阶 + IPC 接触</strong> 可交互，不是把 Ansys 原样搬进 60fps。</p>\n<h2>关键要点</h2>\n<ul>\n<li>选型先问：要手感、要跨材料、还是要绝不穿插。</li>\n<li>调试时先判断属于哪一派，再查对应模块。</li>\n</ul>\n<h2>相关论文 <span class=\"muted\">(12)</span></h2>\n<p class=\"section-note\">按标签自动归入本章。有详细分析的优先点「阅读详细分析」；需要原文再开 arXiv。</p>\n<div class=\"paper-list\">\n<article class=\"paper-card\" id=\"paper-ipc-2020\">\n<p class=\"paper-headline\">IPC：势垒接触保证，FEM 弹性动力学常用底座。</p>\n<p class=\"paper-subline\">无穿插、无翻转接触的变分框架，近五年接触/布料/刚软体工作的地基。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-ipc-2020\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"https://ipc-sim.github.io/\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics\">Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2020-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">fem</span> <span class=\"pill\">contact</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-1802.06895\">\n<p class=\"paper-headline\">MLS-MPM：跨材料粒子-网格混合的高效变体。</p>\n<p class=\"paper-subline\">MLS-MPM 大幅简化/加速 MPM，成为实时与研究实现的常见基石（含 WebGPU 流体实践）。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-1802.06895\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/1802.06895\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling\">A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2018-02-20</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">fluid</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-1602.07039\">\n<p class=\"paper-headline\">XPBD：合规约束，PBD 的生产定型。</p>\n<p class=\"paper-subline\">给 PBD 补上柔度/刚度，减轻迭代次数绑架软硬的问题；现代引擎默认气质。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-1602.07039\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/1602.07039\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"XPBD: Position-Based Simulation of Compliant Constrained Dynamics\">XPBD: Position-Based Simulation of Compliant Constrained Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2016-02-23</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">pbd</span> <span class=\"pill\">xpbd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-pbd-2007\">\n<p class=\"paper-headline\">PBD：位置投影取代力积分，实时稳定优先。</p>\n<p class=\"paper-subline\">定义基于位置的实时约束求解范式，游戏布料/软体默认路线的起点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-pbd-2007\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"https://matthias-research.github.io/pages/publications/posBasedDyn.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Position Based Dynamics\">Position Based Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2007-04-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">pbd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-pb-mpm-2024\">\n<p class=\"paper-headline\">PB-MPM：实时 MPM 的重要工程方向。</p>\n<p class=\"paper-subline\">半隐式约束化 MPM，大步长稳定，实时向。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://dl.acm.org/doi/10.1145/3641233.3664323\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Position Based Material Point Method\">A Position Based Material Point Method</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">realtime</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-2405.11694\">\n<p class=\"paper-headline\">XPBI：位置基方法处理塑性/非弹性。</p>\n<p class=\"paper-subline\">打通 XPBD 与连续介质非弹性，连接游戏约束派与 MPM 气质材料。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/2405.11694\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity\">XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-05-19</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">xpbd</span> <span class=\"pill\">mpm</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-fluid-survey-2024\">\n<p class=\"paper-headline\">流体模拟综述：离散化、多相、细节与控制。</p>\n<p class=\"paper-subline\">近十年流体 CG 综述，入门与查漏适合。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://www.sciopen.com/article/10.1007/s41095-023-0368-y\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges\">Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-04-27</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">fluid</span> <span class=\"pill\">survey</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-diffsim-review-2024\">\n<p class=\"paper-headline\">可微物理模拟器综述。</p>\n<p class=\"paper-subline\">可微模拟器全景；控制/逆问题入口。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://mpan31415.github.io/assets/pdf/papers/2024/IEEEAccess24_DiffSim.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Review of Differentiable Simulators\">A Review of Differentiable Simulators</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-01-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">differentiable</span> <span class=\"pill\">survey</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-cloth-gpu-2024\">\n<p class=\"paper-headline\">GPU 布料：IPC 风格接触的加速。</p>\n<p class=\"paper-subline\">非距离 barrier 砍 CCD；GPU 布料把 IPC 气质推向可交互。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://wanghmin.github.io/publication/lan-2024-egc/Lan-2024-EGC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Efficient GPU Cloth Simulation with Non-distance Barriers and Subspace Reuse\">Efficient GPU Cloth Simulation with Non-distance Barriers and Subspace Reuse</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-01-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">cloth</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-power-plastics-2023\">\n<p class=\"paper-headline\">Power Plastics：砂/泡/液/泡沫等非弹性流。</p>\n<p class=\"paper-subline\">Pixar 参与的中尺度非弹性流；电影向 MPM 系推进。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://research.pixar.com/docs/2023.SiggraphPapers.QLYJ.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Power Plastics: A Hybrid Lagrangian/Eulerian Solver for Mesoscale Inelastic Flows\">Power Plastics: A Hybrid Lagrangian/Eulerian Solver for Mesoscale Inelastic Flows</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2023-12-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">fluid</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-abd-2022\">\n<p class=\"paper-headline\">ABD：仿射体 + IPC，刚度体可快几个数量级。</p>\n<p class=\"paper-subline\">IPC 线上的刚/硬体加速；实证强，但是接触族之一而非新范式。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://dannykaufman.io/projects/ABD/ABD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Affine Body Dynamics: Fast, Stable and Intersection-free Simulation of Stiff Materials\">Affine Body Dynamics: Fast, Stable and Intersection-free Simulation of Stiff Materials</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2022-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">abd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-neural-sph-2024\">\n<p class=\"paper-headline\">Neural SPH：缓解粒子聚团，拉长 rollout。</p>\n<p class=\"paper-subline\">神经流体与 SPH 先验结合；与主线实时引擎关联仍偏研究。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://proceedings.mlr.press/v235/toshev24a.html\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Neural SPH: Improved Neural Modeling of Lagrangian Fluid Dynamics\">Neural SPH: Improved Neural Modeling of Lagrangian Fluid Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-c\">C 档</span> <span>入库 2026-09-30</span> <span>公布 2024-01-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">fluid</span> <span class=\"pill\">neural</span></div>\n</article>\n</div>"}, {"id": "physics-timeline", "module": "物理模拟", "title": "物理时间脉络与落地", "keywords": "Jakobsen PBD Frozen MPM XPBD IPC 时间线 Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics ipc-2020 A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling 1802.06895 XPBD: Position-Based Simulation of Compliant Constrained Dynamics 1602.07039 Position Based Dynamics pbd-2007 A Position Based Material Point Method pb-mpm-2024 XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity 2405.11694 Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges fluid-survey-2024 A Review of Differentiable Simulators diffsim-review-2024 Efficient GPU Cloth Simulation with Non-distance Barriers and Subspace Reuse cloth-gpu-2024 Power Plastics: A Hybrid Lagrangian/Eulerian Solver for Mesoscale Inelastic Flows power-plastics-2023 Affine Body Dynamics: Fast, Stable and Intersection-free Simulation of Stiff Materials abd-2022 Neural SPH: Improved Neural Modeling of Lagrangian Fluid Dynamics neural-sph-2024", "html": "<h1>物理时间脉络与落地</h1>\n<h2>时间线</h2>\n<table><tr><th>年代</th><th>节点</th><th>之前/之后</th><th>落地</th></tr><tr><td>1987–1998</td><td>力/加速度时代</td><td>质点弹簧 / 隐式 FEM（Baraff &amp; Witkin 1998 布料）</td><td>离线动画；游戏难稳</td></tr><tr><td>1999–2003</td><td>网格流体稳定化</td><td>Stam Stable Fluids；SPH 进交互</td><td>烟雾、早期交互水</td></tr><tr><td>2001</td><td>Jakobsen</td><td>Hitman Fysix：Verlet + 位置约束</td><td>游戏布料/尸体</td></tr><tr><td>2006/07</td><td><strong>PBD</strong></td><td>Müller et al. 一般化约束投影</td><td>PhysX 等中间件</td></tr><tr><td>2013</td><td>分水岭</td><td>PBF 液体；Frozen <strong>MPM</strong> 雪</td><td>游戏液 + 电影雪泥</td></tr><tr><td>2014–2016</td><td>精炼</td><td>Projective Dynamics；<strong>XPBD</strong></td><td>现代引擎默认气质</td></tr><tr><td>2018–今</td><td>连续介质 + 硬接触</td><td>MLS-MPM；<strong>IPC</strong> 族；GPU 布料</td><td>实时沙水泥、机器人、堆叠</td></tr></table>\n<h2>口诀</h2>\n<ul>\n<li><strong>布料</strong>：显式弹簧 → 隐式 FEM → 游戏改 Jakobsen/PBD → XPBD/PD → 要绝不穿帮再 IPC。  </li>\n<li><strong>水体</strong>：Stable Fluids/高度场 → SPH → PBF → MPM → 实时 MPM 变体。  </li>\n<li><strong>碰撞</strong>：惩罚/冲量/LCP → PBD 推出 → IPC 势垒。</li>\n</ul>\n<h2>关键要点</h2>\n<ul>\n<li>PBD 正式论文：<strong>2006（VRIPHYS）/ 2007（期刊）</strong>；游戏预告 <strong>Jakobsen 2001</strong>。  </li>\n<li>交互默认长寿；电影/科研突破常在别的赛道。</li>\n</ul>\n<h2>相关论文 <span class=\"muted\">(12)</span></h2>\n<p class=\"section-note\">按标签自动归入本章。有详细分析的优先点「阅读详细分析」；需要原文再开 arXiv。</p>\n<div class=\"paper-list\">\n<article class=\"paper-card\" id=\"paper-ipc-2020\">\n<p class=\"paper-headline\">IPC：势垒接触保证，FEM 弹性动力学常用底座。</p>\n<p class=\"paper-subline\">无穿插、无翻转接触的变分框架，近五年接触/布料/刚软体工作的地基。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-ipc-2020\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"https://ipc-sim.github.io/\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics\">Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2020-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">fem</span> <span class=\"pill\">contact</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-1802.06895\">\n<p class=\"paper-headline\">MLS-MPM：跨材料粒子-网格混合的高效变体。</p>\n<p class=\"paper-subline\">MLS-MPM 大幅简化/加速 MPM，成为实时与研究实现的常见基石（含 WebGPU 流体实践）。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-1802.06895\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/1802.06895\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling\">A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2018-02-20</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">fluid</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-1602.07039\">\n<p class=\"paper-headline\">XPBD：合规约束，PBD 的生产定型。</p>\n<p class=\"paper-subline\">给 PBD 补上柔度/刚度，减轻迭代次数绑架软硬的问题；现代引擎默认气质。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-1602.07039\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/1602.07039\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"XPBD: Position-Based Simulation of Compliant Constrained Dynamics\">XPBD: Position-Based Simulation of Compliant Constrained Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2016-02-23</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">pbd</span> <span class=\"pill\">xpbd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-pbd-2007\">\n<p class=\"paper-headline\">PBD：位置投影取代力积分，实时稳定优先。</p>\n<p class=\"paper-subline\">定义基于位置的实时约束求解范式，游戏布料/软体默认路线的起点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-pbd-2007\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"https://matthias-research.github.io/pages/publications/posBasedDyn.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Position Based Dynamics\">Position Based Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2007-04-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">pbd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-pb-mpm-2024\">\n<p class=\"paper-headline\">PB-MPM：实时 MPM 的重要工程方向。</p>\n<p class=\"paper-subline\">半隐式约束化 MPM，大步长稳定，实时向。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://dl.acm.org/doi/10.1145/3641233.3664323\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Position Based Material Point Method\">A Position Based Material Point Method</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">realtime</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-2405.11694\">\n<p class=\"paper-headline\">XPBI：位置基方法处理塑性/非弹性。</p>\n<p class=\"paper-subline\">打通 XPBD 与连续介质非弹性，连接游戏约束派与 MPM 气质材料。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/2405.11694\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity\">XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-05-19</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">xpbd</span> <span class=\"pill\">mpm</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-fluid-survey-2024\">\n<p class=\"paper-headline\">流体模拟综述：离散化、多相、细节与控制。</p>\n<p class=\"paper-subline\">近十年流体 CG 综述，入门与查漏适合。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://www.sciopen.com/article/10.1007/s41095-023-0368-y\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges\">Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-04-27</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">fluid</span> <span class=\"pill\">survey</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-diffsim-review-2024\">\n<p class=\"paper-headline\">可微物理模拟器综述。</p>\n<p class=\"paper-subline\">可微模拟器全景；控制/逆问题入口。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://mpan31415.github.io/assets/pdf/papers/2024/IEEEAccess24_DiffSim.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Review of Differentiable Simulators\">A Review of Differentiable Simulators</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-01-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">differentiable</span> <span class=\"pill\">survey</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-cloth-gpu-2024\">\n<p class=\"paper-headline\">GPU 布料：IPC 风格接触的加速。</p>\n<p class=\"paper-subline\">非距离 barrier 砍 CCD；GPU 布料把 IPC 气质推向可交互。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://wanghmin.github.io/publication/lan-2024-egc/Lan-2024-EGC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Efficient GPU Cloth Simulation with Non-distance Barriers and Subspace Reuse\">Efficient GPU Cloth Simulation with Non-distance Barriers and Subspace Reuse</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-01-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">cloth</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-power-plastics-2023\">\n<p class=\"paper-headline\">Power Plastics：砂/泡/液/泡沫等非弹性流。</p>\n<p class=\"paper-subline\">Pixar 参与的中尺度非弹性流；电影向 MPM 系推进。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://research.pixar.com/docs/2023.SiggraphPapers.QLYJ.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Power Plastics: A Hybrid Lagrangian/Eulerian Solver for Mesoscale Inelastic Flows\">Power Plastics: A Hybrid Lagrangian/Eulerian Solver for Mesoscale Inelastic Flows</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2023-12-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">fluid</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-abd-2022\">\n<p class=\"paper-headline\">ABD：仿射体 + IPC，刚度体可快几个数量级。</p>\n<p class=\"paper-subline\">IPC 线上的刚/硬体加速；实证强，但是接触族之一而非新范式。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://dannykaufman.io/projects/ABD/ABD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Affine Body Dynamics: Fast, Stable and Intersection-free Simulation of Stiff Materials\">Affine Body Dynamics: Fast, Stable and Intersection-free Simulation of Stiff Materials</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2022-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">abd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-neural-sph-2024\">\n<p class=\"paper-headline\">Neural SPH：缓解粒子聚团，拉长 rollout。</p>\n<p class=\"paper-subline\">神经流体与 SPH 先验结合；与主线实时引擎关联仍偏研究。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://proceedings.mlr.press/v235/toshev24a.html\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Neural SPH: Improved Neural Modeling of Lagrangian Fluid Dynamics\">Neural SPH: Improved Neural Modeling of Lagrangian Fluid Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-c\">C 档</span> <span>入库 2026-09-30</span> <span>公布 2024-01-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">fluid</span> <span class=\"pill\">neural</span></div>\n</article>\n</div>"}, {"id": "physics-realtime-fem", "module": "物理模拟", "title": "实时有限元在 ACG 的进展", "keywords": "FEM FEA IPC GPU 降阶 软体 Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics ipc-2020 A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling 1802.06895 XPBD: Position-Based Simulation of Compliant Constrained Dynamics 1602.07039 Position Based Dynamics pbd-2007 A Position Based Material Point Method pb-mpm-2024 XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity 2405.11694 Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges fluid-survey-2024 A Review of Differentiable Simulators diffsim-review-2024", "html": "<h1>实时有限元在 ACG 的进展</h1>\n<h2>你的旧判断</h2>\n<p>「算力涨了，是不是可以实时有限元？」——<strong>方向对，形态不是工业 FEA 原样进游戏</strong>。</p>\n<h2>实际发生了什么</h2>\n<ul>\n<li>CG 软体/布料学术里早有 FEM，但贵。  </li>\n<li>近十年：隐式 FEM + <strong>IPC 势垒接触</strong> + GPU / 子空间 / 降阶，使中等规模四面体可交互。  </li>\n<li>引擎「软体」常见 <strong>共旋线性 FEM / 降阶 FEM</strong>，不是完整非线性工业套件。</li>\n</ul>\n<h2>分工</h2>\n<table><tr><th>目标</th><th>常见选择</th></tr><tr><td>布料附件、绳子、手感</td><td>XPBD</td></tr><tr><td>大变形、堆不穿、抓取仿真</td><td>FEM + IPC</td></tr><tr><td>水/沙/雪/泥跨材料</td><td>MPM</td></tr></table>\n<h2>关键要点</h2>\n<ul>\n<li>实时「够看的 FEM」更可行了；实时「认证级 FEA」仍不现实。  </li>\n<li>PBD 没死，有限元也没等算力自己变实时——算法与 GPU 一起把轻量 FEM 推进了 ACG。</li>\n</ul>\n<h2>相关论文 <span class=\"muted\">(8)</span></h2>\n<p class=\"section-note\">按标签自动归入本章。有详细分析的优先点「阅读详细分析」；需要原文再开 arXiv。</p>\n<div class=\"paper-list\">\n<article class=\"paper-card\" id=\"paper-ipc-2020\">\n<p class=\"paper-headline\">IPC：势垒接触保证，FEM 弹性动力学常用底座。</p>\n<p class=\"paper-subline\">无穿插、无翻转接触的变分框架，近五年接触/布料/刚软体工作的地基。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-ipc-2020\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"https://ipc-sim.github.io/\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics\">Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2020-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">fem</span> <span class=\"pill\">contact</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-1802.06895\">\n<p class=\"paper-headline\">MLS-MPM：跨材料粒子-网格混合的高效变体。</p>\n<p class=\"paper-subline\">MLS-MPM 大幅简化/加速 MPM，成为实时与研究实现的常见基石（含 WebGPU 流体实践）。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-1802.06895\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/1802.06895\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling\">A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2018-02-20</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">fluid</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-1602.07039\">\n<p class=\"paper-headline\">XPBD：合规约束，PBD 的生产定型。</p>\n<p class=\"paper-subline\">给 PBD 补上柔度/刚度，减轻迭代次数绑架软硬的问题；现代引擎默认气质。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-1602.07039\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/1602.07039\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"XPBD: Position-Based Simulation of Compliant Constrained Dynamics\">XPBD: Position-Based Simulation of Compliant Constrained Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2016-02-23</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">pbd</span> <span class=\"pill\">xpbd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-pbd-2007\">\n<p class=\"paper-headline\">PBD：位置投影取代力积分，实时稳定优先。</p>\n<p class=\"paper-subline\">定义基于位置的实时约束求解范式，游戏布料/软体默认路线的起点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-pbd-2007\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"https://matthias-research.github.io/pages/publications/posBasedDyn.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Position Based Dynamics\">Position Based Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2007-04-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">pbd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-pb-mpm-2024\">\n<p class=\"paper-headline\">PB-MPM：实时 MPM 的重要工程方向。</p>\n<p class=\"paper-subline\">半隐式约束化 MPM，大步长稳定，实时向。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://dl.acm.org/doi/10.1145/3641233.3664323\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Position Based Material Point Method\">A Position Based Material Point Method</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">realtime</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-2405.11694\">\n<p class=\"paper-headline\">XPBI：位置基方法处理塑性/非弹性。</p>\n<p class=\"paper-subline\">打通 XPBD 与连续介质非弹性，连接游戏约束派与 MPM 气质材料。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/2405.11694\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity\">XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-05-19</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">xpbd</span> <span class=\"pill\">mpm</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-fluid-survey-2024\">\n<p class=\"paper-headline\">流体模拟综述：离散化、多相、细节与控制。</p>\n<p class=\"paper-subline\">近十年流体 CG 综述，入门与查漏适合。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://www.sciopen.com/article/10.1007/s41095-023-0368-y\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges\">Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-04-27</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">fluid</span> <span class=\"pill\">survey</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-diffsim-review-2024\">\n<p class=\"paper-headline\">可微物理模拟器综述。</p>\n<p class=\"paper-subline\">可微模拟器全景；控制/逆问题入口。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://mpan31415.github.io/assets/pdf/papers/2024/IEEEAccess24_DiffSim.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Review of Differentiable Simulators\">A Review of Differentiable Simulators</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-01-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">differentiable</span> <span class=\"pill\">survey</span></div>\n</article>\n</div>"}, {"id": "lighting-timeline", "module": "渲染与光照", "title": "光照时间脉络（球谐之后）", "keywords": "SH PRT SSAO SSR 探针 VXGI RT Lumen Precomputed Radiance Transfer for Real-Time Rendering in Dynamic, Low-Frequency Lighting Environments prt-2002 Lumen: Dynamic Global Illumination and Reflections (Unreal Engine 5) lumen-ue5", "html": "<h1>光照时间脉络（球谐之后）</h1>\n<p class=\"lead\">你停在 <strong>球谐（SH）/ PRT（约 2002）</strong>：用低阶基函数扛<strong>低频</strong>间接光，角色可在有遮蔽的 GI 下动。</p>\n<h2>时间线</h2>\n<table><tr><th>年代</th><th>节点</th><th>在干什么</th></tr><tr><td>1975–1986</td><td>局部光</td><td>Phong；Whitted / 路径追踪定数学（离线）</td></tr><tr><td>1996–2001</td><td>烘焙</td><td>Lightmap、环境贴图</td></tr><tr><td>2001–2005</td><td><strong>SH / PRT</strong></td><td>低频动态 GI（你在这附近）</td></tr><tr><td>2005–2012</td><td>Deferred + 屏幕空间</td><td>多灯；SSAO、SSR；探针</td></tr><tr><td>2011–2016</td><td>体素 + <strong>PBR</strong></td><td>VXGI 等；金属度/粗糙度统一材质</td></tr><tr><td>2018–2021</td><td>硬件 RT</td><td>DXR/RTX；DDGI 等</td></tr><tr><td>2021–今</td><td><strong>Lumen</strong> 等</td><td>可动态生产级 GI；路径级实时仍在推进</td></tr></table>\n<h2>SH 之后缺什么、怎么补</h2>\n<ul>\n<li><strong>缺</strong>：高频——清晰镜面、硬阴影、小灯细节；大改场景常要重烤 PRT。  </li>\n<li><strong>补三条线</strong>：屏幕空间（便宜假）· 世界空间缓存（探针/体素/Lumen）· 光线追踪（正确贵）。</li>\n</ul>\n<h2>同一帧分层（调试用）</h2>\n<ol>\n<li>直接光 + 阴影  </li>\n<li>间接漫反射（GI）  </li>\n<li>间接高光 / 反射  </li>\n<li>材质响应（PBR）</li>\n</ol>\n<h2>关键要点</h2>\n<ul>\n<li>球谐不是终点，是「低阶基函数扛间接光」那一代的代表。  </li>\n<li>Lumen ≈ 光照侧后来的生产级动态跃迁（挂在渲染线，不是物理线）。</li>\n</ul>\n<h2>相关论文 <span class=\"muted\">(2)</span></h2>\n<p class=\"section-note\">按标签自动归入本章。有详细分析的优先点「阅读详细分析」；需要原文再开 arXiv。</p>\n<div class=\"paper-list\">\n<article class=\"paper-card\" id=\"paper-prt-2002\">\n<p class=\"paper-headline\">PRT：低频 GI 的经典预计算传递。</p>\n<p class=\"paper-subline\">球谐/PRT 时代代表作；本库光照起点的历史锚点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://www.ppsloan.org/publications/prt.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Precomputed Radiance Transfer for Real-Time Rendering in Dynamic, Low-Frequency Lighting Environments\">Precomputed Radiance Transfer for Real-Time Rendering in Dynamic, Low-Frequency Lighting Environments</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2002-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">lighting</span> <span class=\"pill\">sh</span> <span class=\"pill\">gi</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-lumen-ue5\">\n<p class=\"paper-headline\">Lumen：可动态生产级 GI/反射。</p>\n<p class=\"paper-subline\">工业系统而非论文；但对生产级动态 GI 影响极大，作 C 档锚点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://docs.unrealengine.com/5.0/en-US/lumen-global-illumination-and-reflections-in-unreal-engine/\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Lumen: Dynamic Global Illumination and Reflections (Unreal Engine 5)\">Lumen: Dynamic Global Illumination and Reflections (Unreal Engine 5)</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-c\">C 档</span> <span>入库 2026-09-30</span> <span>公布 2021-05-26</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">lighting</span> <span class=\"pill\">lumen</span> <span class=\"pill\">gi</span></div>\n</article>\n</div>"}, {"id": "pbr-rt-lumen", "module": "渲染与光照", "title": "PBR · 光追 · Lumen", "keywords": "PBR ray tracing Lumen DLSS 混合渲染 Precomputed Radiance Transfer for Real-Time Rendering in Dynamic, Low-Frequency Lighting Environments prt-2002 Lumen: Dynamic Global Illumination and Reflections (Unreal Engine 5) lumen-ue5", "html": "<h1>PBR · 光追 · Lumen</h1>\n<h2>知识缺口（从 SH 出发）</h2>\n<p>主线补齐大致是：<strong>PBR（你已学）→（SSAO/SSR/探针作背景）→ 硬件光追 → Lumen 类动态 GI</strong>。  </p>\n<p>Nanite 不算光照欠账——那是几何。</p>\n<h2>「光追失败了？」</h2>\n<p>相对 <strong>2018 宣传</strong>（开 RT ≈ 取代整套光栅近似且帧率差不多）：<strong>没兑现</strong>。  </p>\n<p>相对 <strong>技术与产品</strong>：光追已嵌进高端/次世代混合管线；失败的是「一步取代」叙事。</p>\n<p>实际赢家：</p>\n<ul>\n<li>光栅主路径 + 局部 RT（反射/阴影/AO）+ 升采样  </li>\n<li>Lumen：软件/硬件追踪混合的可动态 GI</li>\n</ul>\n<h2>英伟达 AI 增强（DLSS 等）</h2>\n<p>确实常被诟病：拖影、鬼影、Frame Generation 造帧与延迟、营销「等效分辨率」。  </p>\n<p>但行业已普遍依赖升采样（DLSS/FSR/XeSS）才能扛高画质+一点 RT——<strong>骂归骂，拐杖已装上</strong>。</p>\n<h2>口诀</h2>\n<p><strong>光栅 + PBR = 底座；RT/Lumen = 可买的正确性；AI 升采样 = 买单用帧率的税。</strong></p>\n<h2>关键要点</h2>\n<ul>\n<li>补课重点：光追在混合管线中的位置 + Lumen 代表的动态 GI。  </li>\n<li>不要把「没取代光栅」理解成「光追没意义」。</li>\n</ul>\n<h2>相关论文 <span class=\"muted\">(2)</span></h2>\n<p class=\"section-note\">按标签自动归入本章。有详细分析的优先点「阅读详细分析」；需要原文再开 arXiv。</p>\n<div class=\"paper-list\">\n<article class=\"paper-card\" id=\"paper-prt-2002\">\n<p class=\"paper-headline\">PRT：低频 GI 的经典预计算传递。</p>\n<p class=\"paper-subline\">球谐/PRT 时代代表作；本库光照起点的历史锚点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://www.ppsloan.org/publications/prt.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Precomputed Radiance Transfer for Real-Time Rendering in Dynamic, Low-Frequency Lighting Environments\">Precomputed Radiance Transfer for Real-Time Rendering in Dynamic, Low-Frequency Lighting Environments</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2002-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">lighting</span> <span class=\"pill\">sh</span> <span class=\"pill\">gi</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-lumen-ue5\">\n<p class=\"paper-headline\">Lumen：可动态生产级 GI/反射。</p>\n<p class=\"paper-subline\">工业系统而非论文；但对生产级动态 GI 影响极大，作 C 档锚点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://docs.unrealengine.com/5.0/en-US/lumen-global-illumination-and-reflections-in-unreal-engine/\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Lumen: Dynamic Global Illumination and Reflections (Unreal Engine 5)\">Lumen: Dynamic Global Illumination and Reflections (Unreal Engine 5)</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-c\">C 档</span> <span>入库 2026-09-30</span> <span>公布 2021-05-26</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">lighting</span> <span class=\"pill\">lumen</span> <span class=\"pill\">gi</span></div>\n</article>\n</div>"}, {"id": "nanite-geometry", "module": "渲染与光照", "title": "Nanite 与几何线", "keywords": "Nanite LOD 虚拟几何 可见性 Nanite Virtualized Geometry (Unreal Engine 5) nanite-ue5", "html": "<h1>Nanite 与几何线</h1>\n<p class=\"lead\">UE5 发布时常与 Lumen 并列的是 <strong>Nanite</strong>：虚拟化微多边形几何。</p>\n<h2>脉络位置</h2>\n<p>手工 LOD / 减面 / 实例化硬扛三角面 → <strong>按屏幕误差流式加载 cluster、软件光栅</strong> → 接近电影级面数进实时。</p>\n<h2>和光照、物理的关系</h2>\n<table><tr><th>技术</th><th>管什么</th></tr><tr><td>Nanite</td><td>几何细节够不够画</td></tr><tr><td>Lumen</td><td>光够不够真、够不够动态</td></tr><tr><td>Chaos / XPBD 等</td><td>物体怎么动</td></tr></table>\n<p>三者叠罗汉，不互相取代。</p>\n<h2>关键要点</h2>\n<ul>\n<li>谈「游戏画面跃迁」时，把几何线与光照线分开记。  </li>\n<li>相关论文标签：<code>nanite</code> / <code>geometry</code> / <code>lod</code> / <code>visibility</code>。</li>\n</ul>\n<h2>相关论文 <span class=\"muted\">(1)</span></h2>\n<p class=\"section-note\">按标签自动归入本章。有详细分析的优先点「阅读详细分析」；需要原文再开 arXiv。</p>\n<div class=\"paper-list\">\n<article class=\"paper-card\" id=\"paper-nanite-ue5\">\n<p class=\"paper-headline\">Nanite：虚拟化微多边形几何。</p>\n<p class=\"paper-subline\">工业几何系统；与 Lumen 并列的 UE5 渲染跃迁锚点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://docs.unrealengine.com/5.0/en-US/nanite-virtualized-geometry-in-unreal-engine/\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Nanite Virtualized Geometry (Unreal Engine 5)\">Nanite Virtualized Geometry (Unreal Engine 5)</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-c\">C 档</span> <span>入库 2026-09-30</span> <span>公布 2021-05-26</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">nanite</span> <span class=\"pill\">geometry</span> <span class=\"pill\">rendering</span></div>\n</article>\n</div>"}, {"id": "other-pillars", "module": "其它支柱", "title": "动画 / 网络 / 开世界等", "keywords": "animation networking streaming ECS motion matching rollback", "html": "<h1>动画 / 网络 / 开世界等</h1>\n<p class=\"lead\">物理与光照之外（音频另说），还有这些主干：</p>\n<table><tr><th>分支</th><th>在干什么</th><th>近年变化感</th></tr><tr><td>渲染其它</td><td>材质、后处理、TAA、粒子、GPU-driven</td><td>持续快</td></tr><tr><td>动画</td><td>骨骼、IK、Motion Matching、学习型动画</td><td>较快</td></tr><tr><td>玩法 AI / 寻路</td><td>Behavior Tree、NavMesh、感知</td><td>中等</td></tr><tr><td>网络同步</td><td>状态同步、Rollback、兴趣管理</td><td>较快（多人）</td></tr><tr><td>开世界流式</td><td>World Partition、HLOD、流式 IO</td><td>较快</td></tr><tr><td>引擎架构</td><td>Job System、ECS、内存</td><td>稳而重</td></tr><tr><td>内容管线</td><td>编辑器、烘焙、CI</td><td>工业权重极大</td></tr><tr><td>UI / 输入 / 相机</td><td>产品层</td><td>计算简单、产品重</td></tr></table>\n<h2>和前两线对照</h2>\n<table><tr><th>已梳理</th><th>同级其它</th></tr><tr><td>物理怎么动</td><td>动画怎么演、AI 怎么决策、网络怎么一致</td></tr><tr><td>光照怎么亮</td><td>几何怎么画、特效/后处理、世界怎么流进来</td></tr></table>\n<h2>关键要点</h2>\n<ul>\n<li>「游戏技术」不是只有物理+光照；但论文感最强的仍常在渲染/物理/动画/网络。  </li>\n<li>本库监控关键词偏图形物理与渲染；其它支柱可后续扩 <code>monitor.json</code>。</li>\n</ul>\n"}, {"id": "paper-index", "module": "论文索引", "title": "分档论文总表", "keywords": "论文 index tier Position Based Dynamics pbd-2007 XPBD: Position-Based Simulation of Compliant Constrained Dynamics 1602.07039 A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling 1802.06895 Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics ipc-2020 Precomputed Radiance Transfer for Real-Time Rendering in Dynamic, Low-Frequency Lighting Environments prt-2002 Affine Body Dynamics: Fast, Stable and Intersection-free Simulation of Stiff Materials abd-2022 Power Plastics: A Hybrid Lagrangian/Eulerian Solver for Mesoscale Inelastic Flows power-plastics-2023 A Review of Differentiable Simulators diffsim-review-2024 Efficient GPU Cloth Simulation with Non-distance Barriers and Subspace Reuse cloth-gpu-2024 Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges fluid-survey-2024 XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity 2405.11694 A Position Based Material Point Method pb-mpm-2024 Lumen: Dynamic Global Illumination and Reflections (Unreal Engine 5) lumen-ue5 Nanite Virtualized Geometry (Unreal Engine 5) nanite-ue5 Neural SPH: Improved Neural Modeling of Lagrangian Fluid Dynamics neural-sph-2024", "html": "<h1>分档论文总表</h1>\n<p class=\"lead\">下方由构建脚本按 A/B/C 列出 <code>indexes/game-tech/index.json</code> 中已入库论文。</p>\n<p>日更未入库的请看 <a href=\"#watchlist\" target=\"_blank\" rel=\"noopener noreferrer\">每日候选项</a>。</p>\n<h2>分档论文</h2>\n<h3>Tier A（4）</h3>\n<div class=\"paper-list\">\n<article class=\"paper-card\" id=\"paper-pbd-2007\">\n<p class=\"paper-headline\">PBD：位置投影取代力积分，实时稳定优先。</p>\n<p class=\"paper-subline\">定义基于位置的实时约束求解范式，游戏布料/软体默认路线的起点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-pbd-2007\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"https://matthias-research.github.io/pages/publications/posBasedDyn.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Position Based Dynamics\">Position Based Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2007-04-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">pbd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-1602.07039\">\n<p class=\"paper-headline\">XPBD：合规约束，PBD 的生产定型。</p>\n<p class=\"paper-subline\">给 PBD 补上柔度/刚度，减轻迭代次数绑架软硬的问题；现代引擎默认气质。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-1602.07039\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/1602.07039\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"XPBD: Position-Based Simulation of Compliant Constrained Dynamics\">XPBD: Position-Based Simulation of Compliant Constrained Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2016-02-23</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">pbd</span> <span class=\"pill\">xpbd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-1802.06895\">\n<p class=\"paper-headline\">MLS-MPM：跨材料粒子-网格混合的高效变体。</p>\n<p class=\"paper-subline\">MLS-MPM 大幅简化/加速 MPM，成为实时与研究实现的常见基石（含 WebGPU 流体实践）。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-1802.06895\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/1802.06895\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling\">A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2018-02-20</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">fluid</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-ipc-2020\">\n<p class=\"paper-headline\">IPC：势垒接触保证，FEM 弹性动力学常用底座。</p>\n<p class=\"paper-subline\">无穿插、无翻转接触的变分框架，近五年接触/布料/刚软体工作的地基。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-primary\" href=\"#paper-ipc-2020\">阅读详细分析</a><a class=\"paper-btn paper-btn-ghost\" href=\"https://ipc-sim.github.io/\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics\">Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2020-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">fem</span> <span class=\"pill\">contact</span></div>\n</article>\n</div>\n<h3>Tier B（8）</h3>\n<div class=\"paper-list\">\n<article class=\"paper-card\" id=\"paper-prt-2002\">\n<p class=\"paper-headline\">PRT：低频 GI 的经典预计算传递。</p>\n<p class=\"paper-subline\">球谐/PRT 时代代表作；本库光照起点的历史锚点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://www.ppsloan.org/publications/prt.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Precomputed Radiance Transfer for Real-Time Rendering in Dynamic, Low-Frequency Lighting Environments\">Precomputed Radiance Transfer for Real-Time Rendering in Dynamic, Low-Frequency Lighting Environments</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2002-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">lighting</span> <span class=\"pill\">sh</span> <span class=\"pill\">gi</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-abd-2022\">\n<p class=\"paper-headline\">ABD：仿射体 + IPC，刚度体可快几个数量级。</p>\n<p class=\"paper-subline\">IPC 线上的刚/硬体加速；实证强，但是接触族之一而非新范式。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://dannykaufman.io/projects/ABD/ABD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Affine Body Dynamics: Fast, Stable and Intersection-free Simulation of Stiff Materials\">Affine Body Dynamics: Fast, Stable and Intersection-free Simulation of Stiff Materials</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2022-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">abd</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-power-plastics-2023\">\n<p class=\"paper-headline\">Power Plastics：砂/泡/液/泡沫等非弹性流。</p>\n<p class=\"paper-subline\">Pixar 参与的中尺度非弹性流；电影向 MPM 系推进。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://research.pixar.com/docs/2023.SiggraphPapers.QLYJ.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Power Plastics: A Hybrid Lagrangian/Eulerian Solver for Mesoscale Inelastic Flows\">Power Plastics: A Hybrid Lagrangian/Eulerian Solver for Mesoscale Inelastic Flows</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2023-12-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">fluid</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-diffsim-review-2024\">\n<p class=\"paper-headline\">可微物理模拟器综述。</p>\n<p class=\"paper-subline\">可微模拟器全景；控制/逆问题入口。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://mpan31415.github.io/assets/pdf/papers/2024/IEEEAccess24_DiffSim.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Review of Differentiable Simulators\">A Review of Differentiable Simulators</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-01-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">differentiable</span> <span class=\"pill\">survey</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-cloth-gpu-2024\">\n<p class=\"paper-headline\">GPU 布料：IPC 风格接触的加速。</p>\n<p class=\"paper-subline\">非距离 barrier 砍 CCD；GPU 布料把 IPC 气质推向可交互。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://wanghmin.github.io/publication/lan-2024-egc/Lan-2024-EGC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Efficient GPU Cloth Simulation with Non-distance Barriers and Subspace Reuse\">Efficient GPU Cloth Simulation with Non-distance Barriers and Subspace Reuse</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-01-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">cloth</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-fluid-survey-2024\">\n<p class=\"paper-headline\">流体模拟综述：离散化、多相、细节与控制。</p>\n<p class=\"paper-subline\">近十年流体 CG 综述，入门与查漏适合。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://www.sciopen.com/article/10.1007/s41095-023-0368-y\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges\">Physics-based fluid simulation in computer graphics: Survey, research trends, and challenges</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-04-27</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">fluid</span> <span class=\"pill\">survey</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-2405.11694\">\n<p class=\"paper-headline\">XPBI：位置基方法处理塑性/非弹性。</p>\n<p class=\"paper-subline\">打通 XPBD 与连续介质非弹性，连接游戏约束派与 MPM 气质材料。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/2405.11694\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity\">XPBI: Position-Based Dynamics with Smoothing Kernels Handles Continuum Inelasticity</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-05-19</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">xpbd</span> <span class=\"pill\">mpm</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-pb-mpm-2024\">\n<p class=\"paper-headline\">PB-MPM：实时 MPM 的重要工程方向。</p>\n<p class=\"paper-subline\">半隐式约束化 MPM，大步长稳定，实时向。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://dl.acm.org/doi/10.1145/3641233.3664323\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Position Based Material Point Method\">A Position Based Material Point Method</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-b\">B 档</span> <span>入库 2026-09-30</span> <span>公布 2024-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">realtime</span></div>\n</article>\n</div>\n<h3>Tier C（3）</h3>\n<div class=\"paper-list\">\n<article class=\"paper-card\" id=\"paper-lumen-ue5\">\n<p class=\"paper-headline\">Lumen：可动态生产级 GI/反射。</p>\n<p class=\"paper-subline\">工业系统而非论文；但对生产级动态 GI 影响极大，作 C 档锚点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://docs.unrealengine.com/5.0/en-US/lumen-global-illumination-and-reflections-in-unreal-engine/\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Lumen: Dynamic Global Illumination and Reflections (Unreal Engine 5)\">Lumen: Dynamic Global Illumination and Reflections (Unreal Engine 5)</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-c\">C 档</span> <span>入库 2026-09-30</span> <span>公布 2021-05-26</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">lighting</span> <span class=\"pill\">lumen</span> <span class=\"pill\">gi</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-nanite-ue5\">\n<p class=\"paper-headline\">Nanite：虚拟化微多边形几何。</p>\n<p class=\"paper-subline\">工业几何系统；与 Lumen 并列的 UE5 渲染跃迁锚点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://docs.unrealengine.com/5.0/en-US/nanite-virtualized-geometry-in-unreal-engine/\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Nanite Virtualized Geometry (Unreal Engine 5)\">Nanite Virtualized Geometry (Unreal Engine 5)</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-c\">C 档</span> <span>入库 2026-09-30</span> <span>公布 2021-05-26</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">nanite</span> <span class=\"pill\">geometry</span> <span class=\"pill\">rendering</span></div>\n</article>\n<article class=\"paper-card\" id=\"paper-neural-sph-2024\">\n<p class=\"paper-headline\">Neural SPH：缓解粒子聚团，拉长 rollout。</p>\n<p class=\"paper-subline\">神经流体与 SPH 先验结合；与主线实时引擎关联仍偏研究。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://proceedings.mlr.press/v235/toshev24a.html\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Neural SPH: Improved Neural Modeling of Lagrangian Fluid Dynamics\">Neural SPH: Improved Neural Modeling of Lagrangian Fluid Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-c\">C 档</span> <span>入库 2026-09-30</span> <span>公布 2024-01-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">fluid</span> <span class=\"pill\">neural</span></div>\n</article>\n</div>"}, {"id": "watchlist", "module": "论文索引", "title": "每日候选项", "keywords": "watchlist inbox monitor 日更", "html": "<h1>每日候选项</h1>\n<p class=\"lead\">监控脚本写入的候选论文会出现在本章下方（构建时读取 <code>watchlist.json</code>）。</p>\n<h2>处理流程</h2>\n<ol>\n<li>看标题/摘要是否贴合物理、渲染或相关标签  </li>\n<li>用 <code>_add_paper.py</code> 分档入库并打 tags  </li>\n<li>需要 A 档时补 <code>indexes/game-tech/core/&lt;id&gt;.md</code>  </li>\n<li><code>python scripts/build_site.py</code>（Actions 会在监控后自动构建 Pages）</li>\n</ol>\n\n<h2>每日候选项</h2><p class=\"section-note\">暂无新候选。最近一次监控：2026-09-30T15:00:00+08:00 · new=0</p>"}, {"id": "tier-a-reading", "module": "论文索引", "title": "A 档精读", "keywords": "A档 核心介绍 Position Based Dynamics pbd-2007 XPBD: Position-Based Simulation of Compliant Constrained Dynamics 1602.07039 Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics ipc-2020 A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling 1802.06895", "html": "<h1>A 档精读</h1>\n<p class=\"lead\">有 <code>core_intro_path</code> 的 A 档论文会在下方展开核心介绍。</p>\n<h2>A 档论文与核心介绍</h2>\n<div class=\"paper-list\">\n<article class=\"paper-card\" id=\"paper-pbd-2007\">\n<p class=\"paper-headline\">PBD：位置投影取代力积分，实时稳定优先。</p>\n<p class=\"paper-subline\">定义基于位置的实时约束求解范式，游戏布料/软体默认路线的起点。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://matthias-research.github.io/pages/publications/posBasedDyn.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Position Based Dynamics\">Position Based Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2007-04-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">pbd</span></div>\n<div class=\"paper-intro\"><ul>\n<li>出处：Müller et al., 2006 VRIPHYS / 2007 JVCIR  </li>\n</ul>\n<h2>主张</h2>\n<p>在位置层直接投影约束，避免显式力积分的过冲；用迭代满足距离/弯曲等约束，再反推速度。</p>\n<h2>为何重要</h2>\n<p>把 Jakobsen 游戏做法一般化，成为实时布料/软体/简单碰撞的默认范式。之后 XPBD、PBF 都站在这条线上。</p>\n<h2>局限</h2>\n<p>刚度与迭代次数、时间步耦合；不是严格能量/连续介质求解。</p>\n<h2>关键要点</h2>\n<ul>\n<li>未知量是位置修正，不是加速度。  </li>\n<li>读代码时抓住：预测 → 投影循环 → 速度回写。</li>\n</ul></div>\n</article>\n<article class=\"paper-card\" id=\"paper-1602.07039\">\n<p class=\"paper-headline\">XPBD：合规约束，PBD 的生产定型。</p>\n<p class=\"paper-subline\">给 PBD 补上柔度/刚度，减轻迭代次数绑架软硬的问题；现代引擎默认气质。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/1602.07039\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"XPBD: Position-Based Simulation of Compliant Constrained Dynamics\">XPBD: Position-Based Simulation of Compliant Constrained Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2016-02-23</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">pbd</span> <span class=\"pill\">xpbd</span></div>\n<div class=\"paper-intro\"><h2>主张</h2>\n<p>用合规（compliance）形式重写位置约束，使软硬更接近物理参数，减轻「多迭代就变硬」的老问题。</p>\n<h2>为何重要</h2>\n<p>生产引擎里说的「基于位置」，多数已是 XPBD 气质。从 PBD 往上补课，这一步仍在同一坐标系。</p>\n<h2>关键要点</h2>\n<ul>\n<li>调参时盯 soft compliance 与 Δt，而不是只加 iteration。  </li>\n<li>仍解决不了「要工业级接触保证」——那是 IPC 的事。</li>\n</ul></div>\n</article>\n<article class=\"paper-card\" id=\"paper-ipc-2020\">\n<p class=\"paper-headline\">IPC：势垒接触保证，FEM 弹性动力学常用底座。</p>\n<p class=\"paper-subline\">无穿插、无翻转接触的变分框架，近五年接触/布料/刚软体工作的地基。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"https://ipc-sim.github.io/\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics\">Incremental Potential Contact: Intersection- and Inversion-free Large-Deformation Dynamics</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2020-07-01</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">ipc</span> <span class=\"pill\">fem</span> <span class=\"pill\">contact</span></div>\n<div class=\"paper-intro\"><ul>\n<li>主页：<a href=\"https://ipc-sim.github.io/\" target=\"_blank\" rel=\"noopener noreferrer\">ipc-sim.github.io</a>  </li>\n</ul>\n<h2>主张</h2>\n<p>把接触做成带势垒的无约束优化，配合 CCD 线搜索，逐步保证无穿插、无翻转，并支持摩擦。</p>\n<h2>为何重要</h2>\n<p>近五年布料/刚软体/抓取仿真大量建立在 IPC 或其加速变体上；是「正确接触」赛道的地基，不是游戏 XPBD 的直接替代品。</p>\n<h2>关键要点</h2>\n<ul>\n<li>贵在接触与非线性求解；GPU/非距离 barrier/子空间在把它推往可交互。  </li>\n<li>调试穿模且越来越穿时，优先怀疑接触模型是否在 IPC 气质的可行域内。</li>\n</ul></div>\n</article>\n<article class=\"paper-card\" id=\"paper-1802.06895\">\n<p class=\"paper-headline\">MLS-MPM：跨材料粒子-网格混合的高效变体。</p>\n<p class=\"paper-subline\">MLS-MPM 大幅简化/加速 MPM，成为实时与研究实现的常见基石（含 WebGPU 流体实践）。</p>\n<div class=\"paper-actions\"><a class=\"paper-btn paper-btn-ghost\" href=\"http://arxiv.org/abs/1802.06895\" target=\"_blank\" rel=\"noopener noreferrer\">原文 arXiv</a></div>\n<p class=\"paper-title-en\" title=\"A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling\">A Moving Least Squares Material Point Method with Displacement Discontinuity and Two-Way Rigid Body Coupling</p>\n<div class=\"paper-meta\"><span class=\"tier-badge tier-a\">A 档</span> <span>入库 2026-09-30</span> <span>公布 2018-02-20</span></div>\n<div class=\"paper-tags\"><span class=\"pill\">physics</span> <span class=\"pill\">mpm</span> <span class=\"pill\">fluid</span></div>\n<div class=\"paper-intro\"><h2>主张</h2>\n<p>用 Moving Least Squares 传递简化 MPM 的力/动量交换，提升效率与实现友好度，并支持断裂与刚体双向耦合等扩展。</p>\n<h2>为何重要</h2>\n<p>MPM 系（含 Frozen 雪）之后，MLS-MPM 成为大量实时/研究实现的默认变体；浏览器 WebGPU 流体实践也常站在这条线上。</p>\n<h2>关键要点</h2>\n<ul>\n<li>适合水/沙/雪/泥跨材料；邻域搜索压力通常低于朴素 SPH。  </li>\n<li>与 PBD 不是替代关系：一个偏连续介质粒子法，一个偏网格约束投影。</li>\n</ul></div>\n</article>\n</div>"}];
